  name: 'AuthorizePayment',
  execute: async () => {
    await paymentGateway.chargeCard(orderId, amount);
  },
  compensate: async () => {
    // Compensating transaction explicitly refunds charged amount
    await paymentGateway.issueRefund(orderId, amount);
  }
};

export async function getCustomerOrderHistory(userId: string) {
  // Query independent service APIs concurrently rather than joining tables directly
  const [user, orders] = await Promise.all([
    userService.fetchUser(userId),
    orderService.fetchOrdersForUser(userId),
  ]);

  // Stitch relational payload in application memory
  return {
    customer: { id: user.id, name: user.name, tier: user.tier },
    orders: orders.map(o => ({ orderId: o.id, total: o.total, status: o.status })),
  };
}

import Consul from 'consul';
const consul = new Consul();

export async function getHealthyServiceEndpoint(serviceName: string): Promise<string> {
  // Query Consul registry for healthy instances only
  const instances: any = await consul.health.service({
    service: serviceName,
    passing: true, // Filters out unhealthy or flapping nodes
  });

  if (!instances || instances.length === 0) {
    throw new Error(`No healthy instances found for ${serviceName}`);
  }

  // Select random instance (client-side load balancing)
  const selected = instances[Math.floor(Math.random() * instances.length)];
  return `http://${selected.Service.Address}:${selected.Service.Port}`;
}

export async function handleMobileDashboard(req: Request, res: Response) {
  const userId = req.headers['x-user-id'] as string;

  // Concurrently fetch from internal microservices over low-latency private VPC
  const [profile, recentOrders, notifications] = await Promise.all([
    userService.getCompactProfile(userId),
    orderService.getRecentSummary(userId, 3),
    notificationService.getUnreadCount(userId),
  ]);

  // Return single, optimized payload tailored specifically for mobile screens
  res.json({
    user: profile,
    orders: recentOrders,
    unreadAlerts: notifications,
  });
}

// Synchronous admission with asynchronous event publication
export async function handleOrderCheckout(req: Request, res: Response) {
  // 1. Fast synchronous validation and persistence
  const order = await orderService.createPendingOrder(req.body);

  // 2. Publish async domain event to Kafka broker
  await kafkaProducer.send({
    topic: 'order-events',
    messages: [{ key: order.id, value: JSON.stringify({ type: 'ORDER_PLACED', order }) }]
  });

  // 3. Return immediately (sub-20ms latency)
  res.status(202).json({
    orderId: order.id,
    status: 'PENDING',
    trackingUrl: `/api/v1/orders/${order.id}`
  });
}

import { trace, context, propagation } from '@opentelemetry/api';

const tracer = trace.getTracer('payment-service');

export async function processPaymentWithTracing(carrierHeaders: Record<string, string>) {
  // 1. Extract incoming W3C traceparent context from HTTP or Kafka headers
  const extractedContext = propagation.extract(context.active(), carrierHeaders);

  // 2. Start a child span linked directly to the upstream caller's trace
  return context.with(extractedContext, async () => {
    const span = tracer.startSpan('execute-stripe-charge');
    try {
      span.setAttribute('payment.gateway', 'stripe');
      const result = await callStripeApi();
      span.setStatus({ code: 1 }); // OK
      return result;
    } catch (err: any) {
      span.recordException(err);
      span.setStatus({ code: 2, message: err.message }); // Error
      throw err;
    } finally {
      span.end();
    }
  });
}

export class DynamicConfig {
  private static config = new Map<string, any>();

  static async initializeWatcher(consul: ConsulClient) {
    const watch = consul.watch({
      method: consul.kv.get,
      options: { key: 'config/production/rate-limits' }
    });

    watch.on('change', (data) => {
      try {
        const parsed = JSON.parse(data.Value);
        this.config.set('rateLimits', parsed);
        console.log('Dynamic configuration reloaded successfully.');
      } catch (err) {
        console.error('Invalid dynamic config syntax! Retaining previous safe config.');
      }
    });
  }

  static get(key: string, defaultValue: any) {
    return this.config.get(key) ?? defaultValue;
  }
}

// 1. Command Side: Executes business validation and updates normalized Write DB
export async function handleCreateOrderCommand(cmd: CreateOrderCommand, writeDb: Database) {
  const order = new Order(cmd.userId, cmd.items);
  order.validateStockAndFunds();
  await writeDb.orders.insert(order.toRow());
  await outbox.publish('OrderCreated', order.toEvent());
}

// 2. Query Side: Asynchronously updates denormalized read view in Elasticsearch
export async function handleOrderCreatedProjection(event: OrderCreatedEvent, elastic: ElasticClient) {
  await elastic.index({
    index: 'orders_search_view',
    id: event.orderId,
    document: {
      orderId: event.orderId,
      customerName: event.customerName,
      totalFormatted: `$${event.total.toFixed(2)}`,
      status: 'PENDING',
      searchKeywords: [event.customerName, ...event.itemNames],
    }
  });
}
